<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hồ sơ MobileX</title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-950 text-slate-100"><main class="mx-auto max-w-5xl p-5 pt-10"><a class="text-blue-300" href="?page=home">← Cửa hàng</a><h1 class="my-5 text-3xl font-bold">Hồ sơ cá nhân</h1><?php if($error): ?><p class="mb-4 rounded bg-red-900 p-3"><?= $e($error) ?></p><?php endif ?><?php if($message): ?><p class="mb-4 rounded bg-emerald-900 p-3"><?= $e($message) ?></p><?php endif ?>
